package dev.alien.client.studio;
import dev.alien.client.AlienClient;import dev.alien.client.gui.*;import dev.alien.client.scene.*;import net.minecraft.client.gui.*;import org.lwjgl.input.*;import java.io.IOException;import java.util.*;
/** Searchable, scrollable cards backed exclusively by actual existing settings. */
public final class ModuleGalleryScreen extends AlienMenuScreen {
    private final GuiScreen back;private final String[] tabs={"Render","Player","HUD","Combat"};private String tab="Render",query="";private int scroll,x,y,w,bottom;private GuiTextField search;private java.util.List<StudioModules.Entry> entries;
    public ModuleGalleryScreen(GuiScreen parent){super(parent);back=parent;}
    public ModuleGalleryScreen openCategory(String category){tab=category;return this;}
    @Override public void initGui(){fontRendererObj=Ui.font();Keyboard.enableRepeatEvents(true);w=Math.min(760,width-24);x=(width-w)/2;y=66;bottom=height-38;search=new GuiTextField(1,fontRendererObj,x+w-155,39,150,19);search.setText(query);search.setMaxStringLength(40);search.setEnableBackgroundDrawing(false);search.setTextColor(Ui.theme().text);rebuild();}
    private void rebuild(){buttonList.clear();entries=new ArrayList<StudioModules.Entry>();for(StudioModules.Entry e:StudioModules.entries(AlienClient.get().config(),AlienClient.get().modules()))if(tab.equals(e.category)&&(e.title+" "+e.description).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))entries.add(e);int tw=Math.min(80,(w-155)/4);for(int i=0;i<tabs.length;i++){if(i==3&&!"unified".equals(dev.alien.client.edition.BuildEdition.ID))continue;buttonList.add(new Ui.Button(i+1,x+i*(tw+3),9,tw,21,tabs[i]).selected(tab.equals(tabs[i])));}buttonList.add(new Ui.Button(5,x+w-103,9,103,21,"Config library"));buttonList.add(new Ui.Button(6,x,height-28,89,20,"Orbit / Studios"));buttonList.add(new Ui.Button(7,x+96,height-28,116,20,"Use this menu"));buttonList.add(new Ui.Button(8,x+w-77,height-28,77,20,"Back"));int cw=(w-10)/2;for(int i=0;i<entries.size();i++){StudioModules.Entry e=entries.get(i);buttonList.add(new Card(100+i,x+(i%2)*(cw+10),y+(i/2)*73-scroll,cw,65,e));}}
    @Override public void drawContents(int mx,int my,float p){Ui.background(width,height);Ui.text("ALIEN / "+tab.toUpperCase(Locale.ROOT),x,43,Ui.theme().text);Ui.rounded(search.xPosition-4,search.yPosition-3,search.width+8,25,6,Ui.alpha(Ui.theme().surfaceRaised,.9f));search.drawTextBox();if(query.isEmpty()&&!search.isFocused())Ui.text("Search modules...",search.xPosition+3,search.yPosition+5,Ui.theme().muted);for(GuiButton b:buttonList)if(b.id<100)b.drawButton(mc,mx,my);float scale=framebufferScale();org.lwjgl.opengl.GL11.glEnable(org.lwjgl.opengl.GL11.GL_SCISSOR_TEST);org.lwjgl.opengl.GL11.glScissor(Math.round(x*scale),mc.displayHeight-Math.round(bottom*scale),Math.round(w*scale),Math.round(Math.max(0,bottom-y)*scale));for(GuiButton b:buttonList)if(b.id>=100)b.drawButton(mc,mx,my);org.lwjgl.opengl.GL11.glDisable(org.lwjgl.opengl.GL11.GL_SCISSOR_TEST);int total=((entries.size()+1)/2)*73;if(total>bottom-y){float fraction=scroll/(float)Math.max(1,total-bottom+y);Ui.rounded(x+w-2,y,2,bottom-y,1,Ui.alpha(Ui.theme().muted,.15f));Ui.rounded(x+w-2,y+fraction*(bottom-y-22),2,22,1,Ui.accent());}}
    @Override protected void actionPerformed(GuiButton b)throws IOException{if(b.id>=1&&b.id<=4){tab=tabs[b.id-1];scroll=0;rebuild();return;}if(b.id==5){mc.displayGuiScreen(new ProfileLibraryScreen(this));return;}if(b.id==6){mc.displayGuiScreen(new StudioOrbitScreen(this));return;}if(b.id==7){AlienClient.get().config().menuLayout="Gallery";AlienClient.get().save();Ui.notify("Gallery set for your menu key");return;}if(b.id==8){mc.displayGuiScreen(back);return;}if(b.id>=100&&b.yPosition>=y-64&&b.yPosition+65>y&&b.yPosition<bottom){entries.get(b.id-100).toggle();AlienClient.get().save();rebuild();}}
    @Override protected void mouseClicked(int mx,int my,int button)throws IOException{search.mouseClicked(mx,my,button);if(button==1){for(GuiButton b:buttonList)if(b.id>=100&&my>=y&&my<bottom&&mx>=b.xPosition&&mx<b.xPosition+b.width&&my>=b.yPosition&&my<b.yPosition+b.height){settings(entries.get(b.id-100));return;}}if(button==0&&my>=y&&my<bottom){for(GuiButton b:buttonList)if(b.id>=100&&mx>=b.xPosition&&mx<b.xPosition+b.width&&my>=b.yPosition&&my<b.yPosition+b.height){actionPerformed(b);return;}}if(my<y||my>=bottom)for(GuiButton b:buttonList)if(b.id<100&&b.mousePressed(mc,mx,my)){actionPerformed(b);break;}}
    private void settings(StudioModules.Entry e){if("scene_sky".equals(e.id))mc.displayGuiScreen(new SceneSkyScreen(this));else if(e.category.equals("HUD"))mc.displayGuiScreen(new dev.alien.client.hud.HudEditorScreen(this));else if(e.category.equals("Combat"))mc.displayGuiScreen(new CombatStudioScreen(this));else if(e.category.equals("Player")||e.id.equals("mist")||e.id.equals("bokeh"))mc.displayGuiScreen(new StudioSettingsScreen(this));else if(e.id.equals("cosmetics"))mc.displayGuiScreen(new dev.alien.client.cosmetic.CosmeticStudioScreen(this));else if(e.id.equals("ambience")||e.id.equals("effects"))mc.displayGuiScreen(new dev.alien.client.world.ParticleStudioScreen(this));else mc.displayGuiScreen(new SceneStudioScreen(this));}
    @Override protected void keyTyped(char ch,int key)throws IOException{if(key==Keyboard.KEY_ESCAPE){mc.displayGuiScreen(back);return;}if(search.textboxKeyTyped(ch,key)){query=search.getText();scroll=0;rebuild();}}
    @Override public void handleMouseInput()throws IOException{super.handleMouseInput();int wheel=Mouse.getEventDWheel();if(wheel!=0){scroll=Math.max(0,Math.min(Math.max(0,((entries.size()+1)/2)*73-(bottom-y)),scroll+(wheel<0?38:-38)));rebuild();}}
    @Override public void updateScreen(){search.updateCursorCounter();}
    @Override public void onGuiClosed(){Keyboard.enableRepeatEvents(false);AlienClient.get().save();}
    @Override public boolean doesGuiPauseGame(){return false;}
    private static final class Card extends Ui.Button {private final StudioModules.Entry entry;Card(int id,int x,int y,int w,int h,StudioModules.Entry e){super(id,x,y,w,h,e.title);entry=e;}@Override public void drawButton(net.minecraft.client.Minecraft m,int mx,int my){hovered=mx>=xPosition&&my>=yPosition&&mx<xPosition+width&&my<yPosition+height;Ui.gradient(xPosition,yPosition,width,height,10,Ui.alpha(Ui.mix(Ui.theme().surfaceRaised,Ui.accent(),entry.enabled()?.16f:.025f),.92f),Ui.alpha(Ui.theme().surface,.85f));Ui.rounded(xPosition+11,yPosition+10,26,26,8,Ui.alpha(Ui.accent(),entry.enabled()?.35f:.12f));Ui.icon(entry.category.equals("HUD")?"grid":"spark",xPosition+17,yPosition+16,14,entry.enabled()?Ui.accent():Ui.theme().muted);Ui.text(Ui.font().trimStringToWidth(entry.title,width-100),xPosition+45,yPosition+12,Ui.theme().text);Ui.rounded(xPosition+width-45,yPosition+12,31,15,7,entry.enabled()?Ui.accent():Ui.alpha(Ui.theme().muted,.22f));Ui.rounded(xPosition+width-(entry.enabled()?28:42),yPosition+14,11,11,5.5f,0xfff4eeff);Ui.text(Ui.font().trimStringToWidth(entry.description,width-24),xPosition+12,yPosition+43,Ui.theme().muted);}}
}
